<script setup lang="ts">
import { ref, watch } from 'vue'
import { Head, router, useForm } from '@inertiajs/vue3'
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'
import SectionNav from '@/Components/SectionNav.vue'

type Person = { id?: number; name?: string; birthdate?: string; sex?: string; municipality?: string; case_count?: number; restricted?: boolean; merged?: boolean; label?: string }
type Candidate = { id:number; status:string; jurisdiction_context:string; matching_signals:{matches:string[]; conflicts:string[]}; left:Person; right:Person; reviewed_at?:string }
type Merge = { id:number; candidate_id:number; status:string; proposed_by:number; proposer_name:string; executed_at?:string }
const props=defineProps<{ candidates:Candidate[]; merges:Merge[]; currentUserId:number; canReview:boolean; canApprove:boolean; canExecute:boolean }>()
const selected=ref<Candidate|null>(null)
const review=useForm({ decision:'insufficient_information', rationale:'' })
const link=useForm({ link_type:'related_person', rationale:'' })
const merge=useForm({ source_client_id:0, survivor_client_id:0, reason:'', field_decisions:[{field_name:'first_name',resolution:'survivor_value',rationale:''}] })
watch(() => props.candidates, (candidates) => { if (selected.value) selected.value = candidates.find(candidate => candidate.id === selected.value?.id) ?? null })
function choose(candidate:Candidate) { selected.value=candidate; review.reset(); link.reset(); merge.reset(); merge.source_client_id=candidate.left.id ?? 0; merge.survivor_client_id=candidate.right.id ?? 0 }
function decide(){ if(selected.value) review.patch(route('identity.review.decision',selected.value.id),{preserveScroll:true,onSuccess:()=>router.reload({only:['candidates']})}) }
function createLink(){ if(selected.value) link.post(route('identity.review.link',selected.value.id),{preserveScroll:true}) }
function propose(){ if(selected.value) merge.post(route('identity.merge.propose',selected.value.id),{preserveScroll:true,onSuccess:()=>router.reload({only:['candidates']})}) }
function approve(item:Merge){ router.patch(route('identity.merge.approve',item.id),{}, {preserveScroll:true,onSuccess:()=>router.reload({only:['candidates','merges']})}) }
function execute(item:Merge){ router.post(route('identity.merge.execute',item.id),{}, {preserveScroll:true,onSuccess:()=>router.reload({only:['candidates','merges']})}) }
function personText(person:Person){ return person.restricted || person.merged ? person.label : person.name }
</script>

<template>
  <Head title="Identity review" />
  <AuthenticatedLayout>
    <main class="identity-review">
      <SectionNav section="cases" />
      <header><p class="eyebrow">IDENTITY INTEGRITY</p><h1>Duplicate and identity review</h1><p>Matching indicators help an authorized reviewer investigate. They never merge people, cases, households, or records automatically.</p></header>
      <section class="privacy-callout"><strong>Minimum necessary review</strong><span>Identifiers, case narratives, Health/SRH content, documents, and assessment content are intentionally excluded from this queue.</span></section>
      <div class="workspace">
        <section aria-label="Potential identity matches" class="candidate-list"><h2>Review queue <span>{{ candidates.length }}</span></h2><p v-if="!candidates.length" class="empty">No candidates within your authorized scope.</p><button v-for="candidate in candidates" :key="candidate.id" type="button" class="candidate" :class="{selected:selected?.id===candidate.id}" @click="choose(candidate)"><span class="status">{{ candidate.status.replaceAll('_',' ') }}</span><strong>{{ personText(candidate.left) }} <span aria-hidden="true">↔</span> {{ personText(candidate.right) }}</strong><small>{{ candidate.jurisdiction_context==='cross_jurisdiction' ? 'Potential match exists in another jurisdiction' : 'Same jurisdiction review' }}</small></button></section>
        <section class="review-detail" aria-live="polite"><template v-if="selected"><div class="detail-heading"><div><p class="eyebrow">CANDIDATE #{{ selected.id }}</p><h2>Compare identity evidence</h2></div><span class="status">{{ selected.status.replaceAll('_',' ') }}</span></div>
          <div class="comparison"><article><h3>Record A</h3><p>{{ personText(selected.left) }}</p><dl v-if="!selected.left.restricted && !selected.left.merged"><dt>Date of birth</dt><dd>{{ selected.left.birthdate || 'Not recorded' }}</dd><dt>Sex</dt><dd>{{ selected.left.sex || 'Not recorded' }}</dd><dt>Locality</dt><dd>{{ selected.left.municipality || 'Not recorded' }}</dd><dt>Cases</dt><dd>{{ selected.left.case_count }}</dd></dl></article><article><h3>Record B</h3><p>{{ personText(selected.right) }}</p><dl v-if="!selected.right.restricted && !selected.right.merged"><dt>Date of birth</dt><dd>{{ selected.right.birthdate || 'Not recorded' }}</dd><dt>Sex</dt><dd>{{ selected.right.sex || 'Not recorded' }}</dd><dt>Locality</dt><dd>{{ selected.right.municipality || 'Not recorded' }}</dd><dt>Cases</dt><dd>{{ selected.right.case_count }}</dd></dl></article></div>
          <div class="signals"><h3>Explainable indicators</h3><p><strong>Matches:</strong> {{ selected.matching_signals.matches.join(', ') || 'None recorded' }}</p><p><strong>Conflicts:</strong> {{ selected.matching_signals.conflicts.join(', ') || 'None recorded' }}</p></div>
          <div v-if="selected.jurisdiction_context==='cross_jurisdiction'" class="blocked"><strong>Cross-jurisdiction safeguard</strong><p>A potential match was found, but full identity details and merge actions are not available without approved inter-LGU governance.</p></div>
          <div v-else-if="canReview && !['merge_proposed','approved','merged'].includes(selected.status)" class="forms"><form @submit.prevent="decide"><h3>Record review decision</h3><label for="identity-decision">Decision</label><select id="identity-decision" v-model="review.decision"><option value="same_person">Same person</option><option value="related_person">Related person</option><option value="different_person">Different person</option><option value="insufficient_information">Insufficient information</option></select><label for="identity-rationale">Rationale</label><textarea id="identity-rationale" v-model="review.rationale" required maxlength="3000" /><button :disabled="review.processing">Save reviewed decision</button></form>
            <form v-if="selected.status==='related_record'" @submit.prevent="createLink"><h3>Link only</h3><label for="identity-link-type">Relationship link</label><select id="identity-link-type" v-model="link.link_type"><option value="related_person">Related person</option><option value="possible_related_record">Possible related record</option></select><label for="identity-link-rationale">Rationale</label><textarea id="identity-link-rationale" v-model="link.rationale" required maxlength="3000" /><button :disabled="link.processing">Create link without merging</button></form>
            <form v-if="selected.status==='confirmed_duplicate'" @submit.prevent="propose"><h3>Propose controlled merge</h3><p class="hint">A merge preserves cases separately. It needs separate approval and execution.</p><label for="identity-source">Source identity</label><select id="identity-source" v-model.number="merge.source_client_id"><option :value="selected.left.id">{{ selected.left.name }}</option><option :value="selected.right.id">{{ selected.right.name }}</option></select><label for="identity-survivor">Canonical survivor</label><select id="identity-survivor" v-model.number="merge.survivor_client_id"><option :value="selected.left.id">{{ selected.left.name }}</option><option :value="selected.right.id">{{ selected.right.name }}</option></select><label for="identity-merge-reason">Reason</label><textarea id="identity-merge-reason" v-model="merge.reason" required maxlength="3000" /><fieldset><legend>Frozen field decision</legend><label for="identity-field">Field</label><select id="identity-field" v-model="merge.field_decisions[0].field_name"><option value="first_name">First name</option><option value="last_name">Last name</option><option value="birthdate">Date of birth</option><option value="sex">Sex</option><option value="municipality">Municipality</option></select><label for="identity-resolution">Resolution</label><select id="identity-resolution" v-model="merge.field_decisions[0].resolution"><option value="survivor_value">Keep survivor value</option><option value="source_value">Use reviewed source value</option><option value="preserve_history">Preserve history; do not overwrite</option></select></fieldset><button :disabled="merge.processing || merge.source_client_id===merge.survivor_client_id">Propose merge for approval</button></form></div>
        </template><p v-else class="empty">Choose a candidate to review the safe identity indicators.</p></section>
      </div>
      <section v-if="merges.length" class="merge-history"><h2>Controlled merge actions</h2><article v-for="item in merges" :key="item.id"><div><strong>Merge proposal #{{ item.id }}</strong><span class="status">{{ item.status }}</span><p>Candidate #{{ item.candidate_id }} · proposed by {{ item.proposer_name }}. Field decisions are frozen at approval.</p></div><div class="merge-actions"><button v-if="canApprove && item.status==='proposed' && item.proposed_by!==currentUserId" @click="approve(item)">Approve merge</button><span v-else-if="item.status==='proposed' && item.proposed_by===currentUserId">A different authorized reviewer must approve.</span><button v-if="canExecute && item.status==='approved'" @click="execute(item)">Execute approved merge</button><span v-if="item.status==='executed'">Executed {{ item.executed_at }}</span></div></article></section>
    </main>
  </AuthenticatedLayout>
</template>

<style scoped>
.identity-review{max-width:1280px;margin:auto;padding:1.25rem;color:#17223b}.eyebrow{font-size:.75rem;font-weight:800;letter-spacing:.08em;color:#6d3bd1;margin:0 0 .35rem}.identity-review h1{margin:0;font-size:clamp(1.5rem,4vw,2.25rem)}header>p{max-width:70ch;color:#5c6d8b}.privacy-callout,.blocked{display:grid;gap:.25rem;padding:1rem;border-radius:.75rem;background:#f5f0ff;border:1px solid #d8c7ff;margin:1.25rem 0}.workspace{display:grid;grid-template-columns:minmax(240px,.7fr) minmax(0,1.8fr);gap:1rem}.candidate-list,.review-detail,.merge-history{background:#fff;border:1px solid #dce4f0;border-radius:1rem;padding:1rem}.candidate-list h2 span{font-size:.8rem;background:#ede7ff;border-radius:999px;padding:.2rem .5rem}.candidate{width:100%;display:grid;text-align:left;gap:.35rem;padding:.9rem;margin:.65rem 0;border:1px solid #dce4f0;border-radius:.75rem;background:#fff;color:inherit}.candidate:hover,.candidate.selected{border-color:#7c3fd1;background:#faf7ff}.candidate small{color:#5c6d8b}.status{display:inline-block;width:max-content;text-transform:capitalize;font-size:.75rem;font-weight:700;padding:.2rem .45rem;border-radius:999px;background:#eef2f7;color:#40536f}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.comparison article,.signals{border:1px solid #e2e8f0;padding:1rem;border-radius:.75rem}.comparison h3,.signals h3,.forms h3{margin-top:0}.comparison p{font-weight:700}dl{display:grid;grid-template-columns:auto 1fr;gap:.45rem;margin:0}dt{color:#5c6d8b}dd{margin:0}.signals{margin-top:1rem}.forms{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-top:1rem}.forms form{border-top:3px solid #7c3fd1;background:#fafcff;padding:1rem;border-radius:.75rem}label{display:grid;gap:.35rem;font-weight:650;margin:.65rem 0}input,select,textarea,button{font:inherit;min-height:2.75rem;border-radius:.5rem;border:1px solid #bfcbdb;padding:.55rem}textarea{min-height:6rem;resize:vertical}button{background:#6d3bd1;color:white;border:0;font-weight:700;cursor:pointer}button:disabled{opacity:.6;cursor:not-allowed}button:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #c4b5fd;outline-offset:2px}.hint,.empty{color:#5c6d8b}.detail-heading,.merge-history article{display:flex;gap:1rem;justify-content:space-between;align-items:start}.merge-history{margin-top:1rem}.merge-history article{padding:.85rem 0;border-top:1px solid #e2e8f0}.merge-history p{color:#5c6d8b;margin:.4rem 0}.merge-actions{display:grid;gap:.5rem;min-width:10rem}@media(max-width:700px){.workspace,.comparison{grid-template-columns:1fr}.identity-review{padding:1rem}.detail-heading,.merge-history article{display:block}.status{margin-top:.5rem}.merge-actions{margin-top:.75rem;min-width:0}}
</style>
